[
  {
    "incident": {
      "component": "PostgreSQL (StatefulSet)",
      "category": "Storage Exhaustion",
      "status": "firing",
      "summary": "The persistent volume claim 'data-postgres-0' in the 'billing' namespace is projected to reach full capacity within 4 hours."
    },
    "assessment": {
      "urgency": "high",
      "rationale": "The storage is filling at 1GiB/h with only 4GiB remaining, meaning a database outage due to disk exhaustion is imminent in approximately 4 hours."
    },
    "facts": [
      "Alert name: KubePersistentVolumeFillingUp",
      "Namespace: billing",
      "PVC: data-postgres-0",
      "Environment: prod",
      "Filesystem size: 50GiB",
      "Available space: 4GiB",
      "Growth rate: 1GiB/h",
      "Storage class: gp3-csi",
      "allow_volume_expansion: true",
      "Workload: Postgres StatefulSet with 1 replica"
    ],
    "missing_context": [
      {
        "item": "Current database transaction logs/WAL size",
        "why": "To determine if the growth is due to data ingestion or runaway WAL generation",
        "how_to_check": "kubectl exec -it data-postgres-0 -n billing -- psql -U postgres -c 'SELECT pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), '0/0'));'"
      },
      {
        "item": "Recent deployment or configuration changes",
        "why": "To see if a recent change triggered increased write activity",
        "how_to_check": "kubectl get events -n billing --sort-by='.lastTimestamp'"
      }
    ],
    "immediate_actions": [
      {
        "action": "Expand the PVC size",
        "purpose": "To prevent imminent database outage by increasing available storage",
        "conditions": "StorageClass must support expansion (confirmed: gp3-csi allows it)",
        "expected_effect": "Increased filesystem capacity without downtime",
        "risks": "Potential filesystem resize latency or errors if the underlying cloud provider limits are hit",
        "requires_approval": true,
        "verify": "kubectl get pvc data-postgres-0 -n billing",
        "rule_ids": [
          "STORAGE_EXPANSION_001"
        ]
      }
    ],
    "investigation_steps": [
      {
        "step": "Check disk usage by directory",
        "hypothesis": "The growth is caused by specific large tables or WAL files",
        "how_to_check": "kubectl exec -it data-postgres-0 -n billing -- du -sh /var/lib/postgresql/data/*"
      },
      {
        "step": "Analyze Postgres growth trends",
        "hypothesis": "The growth is a steady trend rather than a sudden spike",
        "how_to_check": "Prometheus query: rate(container_fs_usage_bytes{persistentvolumeclaim='data-postgres-0'}[1h])"
      }
    ],
    "root_cause_hypotheses": [
      "Increased application write load in the billing service",
      "Unbounded growth of PostgreSQL WAL (Write Ahead Logs) due to replication lag or long-running transactions",
      "Large batch jobs or data migrations running in the billing namespace"
    ],
    "dangerous_operations": [
      {
        "operation": "Deleting files within the Postgres data directory",
        "why_dangerous": "Can lead to immediate database corruption and data loss",
        "rule_id": "DB_DATA_INTEGRITY_001"
      }
    ],
    "applied_expert_rules": [
      "STORAGE_EXPANSION_001"
    ],
    "incident_update": "🚨 *Urgent: Storage Alert* - `data-postgres-0` in `billing` is filling up (4GiB left, ~4h remaining). We are investigating the cause and preparing to expand the PVC via `gp3-csi`."
  }
]
